namespace RecipeShare.Models;

public class RecipeCategory
{
    public string Slug { get; set; } = "";
    public string Name { get; set; } = "";
    public string Icon { get; set; } = "";
    public string Description { get; set; } = "";
}

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = "";
    public string CategorySlug { get; set; } = "";
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

using RecipeShare.Models;

namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<RecipeCategory> _categories =
    [
        new() { Slug = "breakfast", Name = "Breakfast", Icon = "🥞", Description = "Start your day right with pancakes, eggs, smoothies, and more." },
        new() { Slug = "lunch", Name = "Lunch", Icon = "🥗", Description = "Salads, sandwiches, soups, and quick midday meals." },
        new() { Slug = "dinner", Name = "Dinner", Icon = "🍝", Description = "Hearty pastas, roasts, stir-fries, and family favorites." },
        new() { Slug = "desserts", Name = "Desserts", Icon = "🍰", Description = "Cakes, cookies, pies, and sweet treats." },
    ];

    private readonly List<Recipe> _recipes =
    [
        new()
        {
            Id = 1, Title = "Classic Pancakes", CategorySlug = "breakfast",
            Ingredients = ["2 cups flour", "2 eggs", "1½ cups milk", "3 tbsp sugar", "1 tsp baking powder", "Pinch of salt", "Butter for cooking"],
            Steps = ["Mix dry ingredients in a bowl.", "Whisk eggs and milk together, then combine with dry ingredients.", "Heat a buttered pan over medium heat.", "Pour ¼ cup batter per pancake and cook until bubbles form.", "Flip and cook until golden brown."],
            AverageRating = 4.5, RatingCount = 12
        },
        new()
        {
            Id = 2, Title = "Scrambled Eggs", CategorySlug = "breakfast",
            Ingredients = ["4 eggs", "2 tbsp butter", "2 tbsp milk", "Salt and pepper"],
            Steps = ["Whisk eggs with milk, salt, and pepper.", "Melt butter in a non-stick pan over low heat.", "Pour in eggs and stir gently with a spatula.", "Remove from heat when eggs are just set but still creamy."],
            AverageRating = 4.0, RatingCount = 8
        },
        new()
        {
            Id = 3, Title = "Caesar Salad", CategorySlug = "lunch",
            Ingredients = ["1 head romaine lettuce", "½ cup croutons", "¼ cup parmesan cheese", "Caesar dressing", "1 lemon"],
            Steps = ["Wash and chop the romaine lettuce.", "Toss lettuce with Caesar dressing.", "Top with croutons and shaved parmesan.", "Squeeze lemon juice over the top and serve."],
            AverageRating = 4.2, RatingCount = 6
        },
        new()
        {
            Id = 4, Title = "Grilled Cheese Sandwich", CategorySlug = "lunch",
            Ingredients = ["2 slices bread", "2 slices cheddar cheese", "1 tbsp butter"],
            Steps = ["Butter one side of each bread slice.", "Place cheese between the unbuttered sides.", "Cook in a skillet over medium heat until golden on each side."],
            AverageRating = 4.8, RatingCount = 15
        },
        new()
        {
            Id = 5, Title = "Spaghetti Bolognese", CategorySlug = "dinner",
            Ingredients = ["400g spaghetti", "500g ground beef", "1 can crushed tomatoes", "1 onion, diced", "3 cloves garlic", "2 tbsp olive oil", "Salt, pepper, Italian herbs"],
            Steps = ["Cook spaghetti according to package directions.", "Sauté onion and garlic in olive oil.", "Add ground beef and cook until browned.", "Stir in crushed tomatoes and herbs; simmer 20 minutes.", "Serve sauce over spaghetti."],
            AverageRating = 4.7, RatingCount = 20
        },
        new()
        {
            Id = 6, Title = "Chicken Stir-Fry", CategorySlug = "dinner",
            Ingredients = ["2 chicken breasts, sliced", "1 bell pepper", "1 cup broccoli florets", "3 tbsp soy sauce", "1 tbsp sesame oil", "1 clove garlic", "Cooked rice"],
            Steps = ["Heat sesame oil in a wok over high heat.", "Cook chicken slices until golden.", "Add vegetables and garlic; stir-fry 3–4 minutes.", "Pour in soy sauce and toss to coat.", "Serve over rice."],
            AverageRating = 4.3, RatingCount = 10
        },
        new()
        {
            Id = 7, Title = "Chocolate Chip Cookies", CategorySlug = "desserts",
            Ingredients = ["2¼ cups flour", "1 cup butter, softened", "¾ cup sugar", "¾ cup brown sugar", "2 eggs", "1 tsp vanilla", "1 tsp baking soda", "2 cups chocolate chips"],
            Steps = ["Cream butter and sugars together.", "Beat in eggs and vanilla.", "Mix in flour and baking soda.", "Fold in chocolate chips.", "Drop spoonfuls onto a baking sheet.", "Bake at 375°F (190°C) for 9–11 minutes."],
            AverageRating = 4.9, RatingCount = 25
        },
        new()
        {
            Id = 8, Title = "Banana Bread", CategorySlug = "desserts",
            Ingredients = ["3 ripe bananas", "⅓ cup melted butter", "¾ cup sugar", "1 egg", "1 tsp vanilla", "1 tsp baking soda", "1½ cups flour"],
            Steps = ["Preheat oven to 350°F (175°C).", "Mash bananas and mix with melted butter.", "Stir in sugar, egg, and vanilla.", "Add baking soda and flour; mix until just combined.", "Pour into a greased loaf pan.", "Bake for 60–65 minutes."],
            AverageRating = 4.6, RatingCount = 18
        },
    ];

    // Tracks ratings per session (in-memory only)
    private readonly Dictionary<(int RecipeId, string SessionId), int> _userRatings = new();

    public List<RecipeCategory> GetCategories() => _categories;

    public RecipeCategory? GetCategory(string slug) =>
        _categories.FirstOrDefault(c => c.Slug == slug);

    public List<Recipe> GetRecipesByCategory(string categorySlug) =>
        _recipes.Where(r => r.CategorySlug == categorySlug).ToList();

    public Recipe? GetRecipe(int id) =>
        _recipes.FirstOrDefault(r => r.Id == id);

    public void SubmitRating(int recipeId, int stars, string sessionId)
    {
        var recipe = GetRecipe(recipeId);
        if (recipe is null || stars < 1 || stars > 5) return;

        var key = (recipeId, sessionId);
        if (_userRatings.TryGetValue(key, out var previous))
        {
            // Update: remove old rating contribution, add new one
            var totalStars = recipe.AverageRating * recipe.RatingCount;
            totalStars = totalStars - previous + stars;
            recipe.AverageRating = Math.Round(totalStars / recipe.RatingCount, 1);
        }
        else
        {
            var totalStars = recipe.AverageRating * recipe.RatingCount + stars;
            recipe.RatingCount++;
            recipe.AverageRating = Math.Round(totalStars / recipe.RatingCount, 1);
        }
        _userRatings[key] = stars;
    }

    public int? GetUserRating(int recipeId, string sessionId)
    {
        return _userRatings.TryGetValue((recipeId, sessionId), out var rating) ? rating : null;
    }

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _recipes.Count > 0 ? _recipes.Max(r => r.Id) + 1 : 1;
        _recipes.Add(recipe);
    }
}

