@page "/"
@using RecipeShare.Services

<PageTitle>RecipeShare — Home</PageTitle>

<h1>🍽️ Welcome to RecipeShare</h1>
<p class="lead">Discover and share delicious recipes with our community.</p>

<h2 class="mt-4">Browse by Category</h2>
<div class="row mt-3">
    @foreach (var cat in RecipeService.GetCategories())
    {
        <div class="col-md-3 col-sm-6 mb-4">
