                    <div style="font-size:3rem;">@cat.Icon</div>
                    <h5 class="card-title mt-2">@cat.Name</h5>
                    <p class="card-text">@cat.Description</p>
                    <a href="category/@cat.Slug" class="btn btn-primary">Browse</a>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Inject] public required RecipeService RecipeService { get; set; }
}

