@page "/category/{Slug}"
@using RecipeShare.Services
@using RecipeShare.Models

<PageTitle>@(category?.Name ?? "Category") — RecipeShare</PageTitle>

@if (category is null)
{
    <h1>Category not found</h1>
    <p>Sorry, we couldn't find that category. <a href="/">Go back home</a>.</p>
}
else
{
    <h1>@category.Icon @category.Name</h1>
    <p class="lead">@category.Description</p>

    var recipes = RecipeService.GetRecipesByCategory(Slug);

    @if (recipes.Count == 0)
    {
        <div class="alert alert-info">No recipes in this category yet. <a href="submit">Submit one!</a></div>
    }
    else
    {
        <div class="row mt-3">
            @foreach (var recipe in recipes)
            {
                <div class="col-md-4 col-sm-6 mb-4">
                    <div class="card h-100">
                        <div class="card-body">
                            <h5 class="card-title">@recipe.Title</h5>
                            <p class="card-text">
                                <span class="text-warning">@(new string('★', (int)Math.Round(recipe.AverageRating)))@(new string('☆', 5 - (int)Math.Round(recipe.AverageRating)))</span>
                                <small class="text-muted">(@recipe.AverageRating / 5 · @recipe.RatingCount ratings)</small>
                            </p>
                            <a href="recipe/@recipe.Id" class="btn btn-outline-primary">View Recipe</a>
                        </div>
                    </div>
                </div>
            }
        </div>
    }
}

@code {
    [Parameter] public string Slug { get; set; } = "";
    [Inject] public required RecipeService RecipeService { get; set; }

    private RecipeCategory? category;

    protected override void OnParametersSet()
    {
        category = RecipeService.GetCategory(Slug);
    }
}

@page "/recipe/{Id:int}"
@using RecipeShare.Services
@using RecipeShare.Models

<PageTitle>@(recipe?.Title ?? "Recipe") — RecipeShare</PageTitle>

@if (recipe is null)
{
    <h1>Recipe not found</h1>
    <p><a href="/">Go back home</a>.</p>
}
else
{
    var category = RecipeService.GetCategory(recipe.CategorySlug);

    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="category/@recipe.CategorySlug">@(category?.Name ?? recipe.CategorySlug)</a></li>
            <li class="breadcrumb-item active">@recipe.Title</li>
        </ol>
    </nav>

    <h1>@recipe.Title</h1>

    <div class="mb-3">
        <span class="text-warning" style="font-size:1.2rem;">
            @(new string('★', (int)Math.Round(recipe.AverageRating)))@(new string('☆', 5 - (int)Math.Round(recipe.AverageRating)))
        </span>
        <span class="text-muted">@recipe.AverageRating / 5 (@recipe.RatingCount ratings)</span>
    </div>

    <StarRating RecipeId="recipe.Id" />

    <h3 class="mt-4">Ingredients</h3>
    <ul class="list-group list-group-flush mb-4">
        @foreach (var ingredient in recipe.Ingredients)
        {
            <li class="list-group-item">@ingredient</li>
        }
    </ul>

    <h3>Steps</h3>
    <ol class="list-group list-group-numbered mb-4">
        @foreach (var step in recipe.Steps)
        {
            <li class="list-group-item">@step</li>
        }
    </ol>
}

@code {
    [Parameter] public int Id { get; set; }
    [Inject] public required RecipeService RecipeService { get; set; }

    private Recipe? recipe;

    protected override void OnParametersSet()
    {
        recipe = RecipeService.GetRecipe(Id);
    }
}

@rendermode InteractiveServer
@using RecipeShare.Services

<div class="card my-3" style="max-width: 350px;">
    <div class="card-body">
        <h6 class="card-subtitle mb-2 text-muted">Rate this recipe</h6>
        <div style="font-size: 1.8rem; cursor: pointer; user-select: none;">
            @for (int i = 1; i <= 5; i++)
            {
                var star = i;
                <span @onclick="() => Rate(star)"
                      @onmouseover="() => hovered = star"
                      @onmouseout="() => hovered = 0"
                      class="@(star <= DisplayStars ? "text-warning" : "text-secondary")">
                    @(star <= DisplayStars ? "★" : "☆")
                </span>
            }
        </div>
        @if (submitted)
        {
            <small class="text-success">Thanks! You rated this @userRating/5 stars.</small>
        }
    </div>
</div>

@code {
    [Parameter] public required int RecipeId { get; set; }
    [Inject] public required RecipeService RecipeService { get; set; }

    private int hovered;
    private int userRating;
    private bool submitted;
    private string sessionId = Guid.NewGuid().ToString();

    private int DisplayStars => hovered > 0 ? hovered : userRating;

    protected override void OnParametersSet()
    {
        var existing = RecipeService.GetUserRating(RecipeId, sessionId);
        if (existing.HasValue)
        {
            userRating = existing.Value;
            submitted = true;
        }
    }

    private void Rate(int stars)
    {
        userRating = stars;
        submitted = true;
        RecipeService.SubmitRating(RecipeId, stars, sessionId);
    }
}

@page "/submit"
@rendermode InteractiveServer
@using RecipeShare.Models
@using RecipeShare.Services

<PageTitle>Submit a Recipe — RecipeShare</PageTitle>

<h1>📝 Submit a Recipe</h1>
<p>Share your favorite recipe with the community!</p>

@if (successMessage is not null)
{
    <div class="alert alert-success">@successMessage <a href="recipe/@newRecipeId">View your recipe</a>.</div>
}

<EditForm Model="model" OnValidSubmit="HandleSubmit" FormName="submitRecipe" class="mt-3" style="max-width: 600px;">
    <DataAnnotationsValidator />
    <ValidationSummary class="text-danger" />

    <div class="mb-3">
        <label for="title" class="form-label">Recipe Title</label>
        <InputText id="title" @bind-Value="model.Title" class="form-control" placeholder="e.g., Grandma's Apple Pie" />
        <ValidationMessage For="() => model.Title" class="text-danger" />
    </div>

    <div class="mb-3">
        <label for="category" class="form-label">Category</label>
        <InputSelect id="category" @bind-Value="model.CategorySlug" class="form-select">
            <option value="">— Select a category —</option>
            @foreach (var cat in RecipeService.GetCategories())
            {
                <option value="@cat.Slug">@cat.Icon @cat.Name</option>
            }
        </InputSelect>
        <ValidationMessage For="() => model.CategorySlug" class="text-danger" />
    </div>

    <div class="mb-3">
        <label for="ingredients" class="form-label">Ingredients</label>
        <InputTextArea id="ingredients" @bind-Value="model.Ingredients" class="form-control" rows="5"
                       placeholder="One ingredient per line&#10;e.g.,&#10;2 cups flour&#10;1 cup sugar" />
        <ValidationMessage For="() => model.Ingredients" class="text-danger" />
        <div class="form-text">Enter one ingredient per line.</div>
    </div>

    <div class="mb-3">
        <label for="steps" class="form-label">Steps</label>
        <InputTextArea id="steps" @bind-Value="model.Steps" class="form-control" rows="5"
                       placeholder="One step per line&#10;e.g.,&#10;Preheat oven to 350°F&#10;Mix dry ingredients" />
        <ValidationMessage For="() => model.Steps" class="text-danger" />
        <div class="form-text">Enter one step per line.</div>
    </div>

    <button type="submit" class="btn btn-primary">Submit Recipe</button>
</EditForm>

@code {
    [Inject] public required RecipeService RecipeService { get; set; }

    private SubmitRecipeModel model = new();
    private string? successMessage;
    private int newRecipeId;

    private void HandleSubmit()
    {
        var recipe = new Recipe
        {
            Title = model.Title,
            CategorySlug = model.CategorySlug,
            Ingredients = model.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList(),
            Steps = model.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList(),
        };

        RecipeService.AddRecipe(recipe);
        newRecipeId = recipe.Id;
        successMessage = $"'{recipe.Title}' submitted successfully!";
        model = new();
    }
}

