+    private int DisplayStars => hovered > 0 ? hovered : userRating;
+
+    protected override void OnParametersSet()
+    {
+        var existing = RecipeService.GetUserRating(RecipeId, sessionId);
+        if (existing.HasValue)
+        {
+            userRating = existing.Value;
+            submitted = true;
+        }
+    }
+
+    private void Rate(int stars)
+    {
+        userRating = stars;
+        submitted = true;
+        RecipeService.SubmitRating(RecipeId, stars, sessionId);
+    }
+}
